import React, { useState } from 'react';
import { Grommet, Box, DateInput } from 'grommet';

const TimezoneBoundsBugExample = () => {
  // defaultValue includes an -08:00 timezone offset
  const [value, setValue] = useState('2020-07-02T00:00:00-08:00');

  return (
    <Grommet>
      <Box pad="large">
        <DateInput
          value={value}
          onChange={({ value: nextValue }) => setValue(nextValue)}
          // We only want dates from July 1 through July 31, 2020
          calendarProps={{ bounds: ['2020-07-01', '2020-07-31'] }}
        />
      </Box>
    </Grommet>
  );
};

export default TimezoneBoundsBugExample;
